pub fn namespace_graft_has_explicit_braced_container(root: Rc<Node>, first_segment: std::string::String) -> bool {
    {
        let working = crate::v2_extdeps_languages_dag::namespace_graft_unwrap_module_working_root(root);
working.children.clone().iter().cloned().fold(false, |found: bool, edge: Rc<Edge>| if found {
            true
        } else {
            match (*edge.label.clone()).clone() {
    EdgeLabel::StructuralLabel { label: _, .. } => false,
    EdgeLabel::Authored { name: sym, .. } => if (sym.clone() == first_segment.clone()) {
                match (*edge.target.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => true,
    Connective::Atom { identity: _, .. } => false,
    Connective::Disj => false,
    Connective::Arrow => false,
    Connective::Instantiation => false,
} },
    NodeKind::ComputationNode { behavior: _, .. } => false,
}
            } else {
                false
            },
    EdgeLabel::Positional => false,
}
        })
}
}

pub fn namespace_graft_dual_position_refused(root: Rc<Node>) -> bool {
    if !namespace_graft_is_graft_candidate(root.clone()) {
        false
    } else {
        match (*crate::v2_extdeps_languages_dag::qualified_name_from_module_node(root.clone())).clone() {
    Outcome::Rejected { diagnostics: _, .. } => false,
    Outcome::Accepted { value: qn, .. } => { let __fm = qn.clone(); if __fm.is_empty() { false } else { let first = (*__fm)[0].clone(); namespace_graft_has_explicit_braced_container(root.clone(), first.clone()) } },
}
    }
}

